// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address player = address(0xB0B);
    address bankClaim;

    function setUp() public {
        c = new C();
        bankClaim = c.bank();
        vm.deal(bankClaim, 1 ether);
        vm.deal(player, 1000 ether);
    }

    function testFuzz_property(uint256 seed) public {
        vm.assume(seed > 0);
        bool found = false;
        for (uint256 i = 1; i <= 256; i++) {
            vm.warp(seed + i);
            uint256 beforeBal = address(player).balance;
            vm.prank(player);
            c.play{value: 10}();
            // If the caller was NOT paid out, the round was a "loss" (random == 1):
            // the caller's balance dropped by exactly the ticket price and nothing else.
            if (address(player).balance == beforeBal - 10) {
                // General rule: a losing play accumulates exactly TICKET_AMOUNT into the pot.
                assertTrue(c.pot() == 10, "pot must grow by ticket amount on a losing play");
                found = true;
                break;
            } else {
                // winning round: pot was drained; player got refunded pot - FEE
                vm.deal(player, 1000 ether);
            }
        }
        // The fuzzer explores timestamps; almost always at least one losing round occurs.
        assertTrue(!found || c.pot() == 10);
    }
}

