// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, uint256 bl, address player) public {
        // keep params in admissible domain; domain stays wide
        vm.assume(player != address(0) && player != address(c) && player != address(this));
        vm.warp(ts);
        vm.roll(bound(bl, 1, type(uint64).max));

        // fund the player and the pot contract so all internal transfers succeed
        vm.deal(player, 1e30);
        vm.deal(address(c), 1e30);

        uint potBefore = c.pot();
        bool ok;
        vm.prank(player);
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }

        potBefore; // referenced state via getter above
        // RULE: a correctly-valued, fully-funded play NEVER reverts (loss adds to pot,
        // win pays out cleanly and zeroes pot). The mutant reverts on every win
        // (pot - FEE_AMOUNT underflows after pot = 0), so for some seeds ok == false.
        assertTrue(ok, "play with exact ticket amount must not revert");
    }
}

