pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    receive() external payable {} // the contract is the bank; it must be able to receive FEE_AMOUNT

    function testFuzz_property(uint256 timestamp, address actor) public {
        // Admissible domain: any timestamp, caller must be an EOA with no code
        // (a contract caller could reject the 2300-gas payout transfer, which the
        // reference legitimately cannot avoid).
        vm.assume(actor.code.length == 0);
        vm.deal(actor, 10);
        vm.warp(timestamp);

        vm.prank(actor);
        bool ok;
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "play with exact ticket amount must not revert");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public {
        require(amount == 10);
        require(address(this).balance >= amount);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.play.selector));
        assert(ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(uint amount) external {
        require(amount == 10); // must equal C.TICKET_AMOUNT for play() to succeed
        require(address(this).balance >= 2 * amount);
        uint balanceBefore = address(this).balance;

        c.play{value: amount}();
        c.play{value: amount}();

        // Each winning play can refund at most (pot - FEE) <= (amount - 1),
        // since on P the pot is reset to 0 after every win, so the pot at any
        // play is at most one ticket. Two plays => total refund <= 2*(amount-1).
        assert(address(this).balance - balanceBefore <= 2 * (amount - 1));
    }

    receive() external payable {}
    fallback() external payable {}
}

