contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);
        uint potBefore = c.pot();
        bool reverted = false;
        try c.play{value: amount}() {
            // succeeded
        } catch {
            reverted = true;
        }
        uint potAfter = c.pot();
        assert(!reverted && (potAfter == potBefore + amount || potAfter == 0));
    }
    receive() external payable {}
}
